<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);
spl_autoload_register(static function(string $class) use($root):void{$prefix='App\\';if(!str_starts_with($class,$prefix))return;$file=$root.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require_once $file;});
try{$pdo=\App\Core\Database::connection();$db=(string)$pdo->query('SELECT DATABASE()')->fetchColumn();echo "Banco: {$db}\n";$checks=[['subscriptions','base_contracted_price'],['subscriptions','addon_contracted_price'],['tenant_module_addons','billing_mode'],['checkout_sessions','base_total'],['checkout_sessions','addon_total']];foreach($checks as [$table,$column]){$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c');$q->execute(['t'=>$table,'c'=>$column]);echo ((int)$q->fetchColumn()>0?'[OK] ':'[FALTA] ').$table.'.'.$column."\n";}$table=(int)$pdo->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='subscription_module_adjustments'")->fetchColumn();echo ($table?'[OK] ':'[FALTA] ')."subscription_module_adjustments\n";$legacy=(int)$pdo->query("SELECT COUNT(*) FROM tenant_module_addons WHERE status='active' AND COALESCE(billing_mode,'separate')='separate'")->fetchColumn();$merged=(int)$pdo->query("SELECT COUNT(*) FROM tenant_module_addons WHERE status='active' AND COALESCE(billing_mode,'separate')='merged_subscription'")->fetchColumn();$sync=(int)$pdo->query("SELECT COUNT(*) FROM subscription_module_adjustments WHERE status='sync_required'")->fetchColumn();echo "Ativos incorporados: {$merged}\nAtivos legados separados: {$legacy}\nAjustes exigindo sincronização manual: {$sync}\n";if($sync>0)echo "[ATENÇÃO] Há ajustes sync_required. Não altere cobrança manualmente sem conferir Mercado Pago e banco local.\n";}catch(Throwable $e){fwrite(STDERR,"[ERRO] {$e->getMessage()}\n");exit(1);}
